WITH c AS (SELECT claim_id, SUM(CASE WHEN txn_type='RESERVE' THEN amount ELSE 0 END) res, SUM(CASE WHEN txn_type='PAYMENT' THEN amount ELSE 0 END) pd, SUM(CASE WHEN txn_type='RECOVERY' THEN amount ELSE 0 END) rec, COUNT(*) n FROM claim_txn GROUP BY 1)
SELECT COUNT(*) claims, SUM(CASE WHEN res<0 THEN 1 ELSE 0 END) neg_res_claims, SUM(res) res_sum, SUM(pd) pd_sum, SUM(rec) rec_sum FROM c;
SELECT txn_type, cost_type, SUM(CASE WHEN amount<0 THEN 1 ELSE 0 END) neg, SUM(CASE WHEN amount>0 THEN 1 ELSE 0 END) pos FROM claim_txn GROUP BY 1,2;
SELECT c.claim_id, c.accident_date, c.closed_date, t.txn_date, t.txn_type, t.cost_type, t.amount FROM claim c JOIN claim_txn t USING(claim_id) WHERE c.claim_id IN (SELECT claim_id FROM claim_txn ORDER BY random() LIMIT 3) ORDER BY 1,4;
